.pwd-wrap { display: flex; flex-direction: column; gap: 15px; width: 250px; font-family: sans-serif; }
.pwd-input {
  width: 100%; padding: 15px; border: none; border-radius: 8px;
  background: rgba(255,255,255,0.1); color: #fff; font-size: 16px; outline: none;
  box-sizing: border-box; transition: box-shadow 0.3s;
}
.pwd-input:focus { box-shadow: 0 0 10px rgba(0, 210, 255, 0.5); }
.meter-bars { display: flex; gap: 5px; height: 6px; width: 100%; }
.bar { flex: 1; background: #333; border-radius: 3px; transition: background 0.4s ease; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'pwd-wrap';

const input = document.createElement('input');
input.className = 'pwd-input';
input.type = 'password';
input.placeholder = 'Type password...';

const meter = document.createElement('div');
meter.className = 'meter-bars';
const bars = Array.from({length: 4}, () => {
  const b = document.createElement('div');
  b.className = 'bar'; meter.appendChild(b); return b;
});

wrap.appendChild(input); wrap.appendChild(meter);
c.appendChild(wrap);

input.addEventListener('input', (e) => {
  const len = e.target.value.length;
  bars.forEach(b => b.style.background = '#333');
  if(len > 0) bars[0].style.background = '#ff4d4d'; // Weak
  if(len > 4) { bars[0].style.background = '#ffa64d'; bars[1].style.background = '#ffa64d'; } // Fair
  if(len > 7) { bars.slice(0,3).forEach(b => b.style.background = '#ffff4d'); } // Good
  if(len > 10) { bars.forEach(b => b.style.background = '#00ffcc'); } // Strong
});
